r.append(R(3763,"سالسا ورڈے","سالسا ورڈے چکن اینچیلاداس کے لیے مزیدار ساس ہے، لیکن انڈوں، ٹیکو یا آپ کی پسندیدہ میکسیکن ڈش کے اوپر ڈالنے کے لیے بھی بہترین ہے۔","10","1/4 کپ",
["6 درمیانے ٹماٹیلو (تقریباً 1/2 پاؤنڈ)","1 درمیانی ہالاپینو مرچ","1/2 چھوٹی سفید یا پیلی پیاز","1 لہسن کی کلی","1/4 کپ دبا کر بھرے ہوئے تازہ ہرا دھنیا کے پتے","1/4 چائے کا چمچ نمک","1/4 چائے کا چمچ کالی مرچ","1 چائے کا چمچ لائم کا رس"],
["ٹماٹیلو کو ایک درمیانے پیالے میں پانی میں 5 منٹ بھگو دیں۔ ٹماٹیلو کو پانی کے نیچے ڈوبا رکھنے کے لیے ان کے اوپر ایک چھوٹی پلیٹ رکھ دیں۔ جب ٹماٹیلو بھیگ رہے ہوں، کناروں والی بیکنگ شیٹ پر ایلومینیم فوائل لگائیں اور براؤلر کو پہلے سے گرم کریں، ریک کو حرارت کے ذریعے سے 4 انچ نیچے رکھیں۔","بھیگے ہوئے ٹماٹیلو کے چھلکے اور ڈنٹھل اتار دیں۔ چھلکے پر باقی چپچپا مادہ دھو کر صاف کر دیں۔ ٹماٹیلو کو خشک کر کے آدھا آدھا کاٹ لیں۔","ہالاپینو کا ڈنٹھل نکال کر چار حصوں میں کاٹ لیں۔ پیاز کو چار حصوں میں کاٹ لیں۔","ٹماٹیلو اور ہالاپینو کو کٹے ہوئے رخ نیچے کی طرف رکھ کر تیار کی گئی بیکنگ شیٹ پر رکھیں۔ لہسن کی کلی اور چار حصوں والی پیاز بھی بیکنگ شیٹ پر رکھیں۔ ہلکا بھورا ہونے تک یا چھوٹے جلے ہوئے دھبے نظر آنے تک 5 سے 7 منٹ براؤل کریں۔ ضرورت کے مطابق وقت ایڈجسٹ کریں اور احتیاط سے دیکھتے رہیں کیونکہ یہ جلدی جل سکتے ہیں۔ اوون سے نکال لیں۔","براؤل کی ہوئی چیزوں کو ان کے رس سمیت احتیاط سے فوڈ پروسیسر یا بلینڈر میں منتقل کریں۔ ہرا دھنیا، لائم کا رس، نمک اور کالی مرچ ڈالیں۔","مکسچر کو اس وقت تک پلس کریں جب تک وہ ہموار نہ ہو جائے اور ٹماٹیلو کے بڑے ٹکڑے باقی نہ رہیں۔ احتیاط کریں کہ اسے پیوری نہ بنائیں۔ سالسا پتلا ہوگا، تاہم چند گھنٹے فرج میں رکھنے کے بعد گاڑھا ہو جائے گا۔"],
["ہلکا مرچ والا سالسا بنانے کے لیے ہالاپینو کے بیج اور رگیں نکال دیں، یا تیکھا پن بڑھانے کے لیے ایک اور ہالاپینو ڈالیں۔","سخت ٹماٹیلو تلاش کریں۔ ٹماٹیلو کو بھگونے سے چھلکے سے چپچپا مادہ ہٹانے میں مدد ملتی ہے۔","سالسا ورڈے کو ہوا بند ڈبے میں فرج میں ایک ہفتے تک یا مستقبل کے استعمال کے لیے فریزر میں محفوظ کیا جا سکتا ہے۔","انڈوں، ٹیکو یا اپنی پسندیدہ میکسیکن ڈش پر گرم یا ٹھنڈا پیش کریں۔"],
["1/2 سبزی، کم پوٹاشیم والی"]))
r.append(R(3765,"گاجر اور سیب کیسرول","نارتھ کیرولائنا سے ڈی ویٹا کی گردوں کی غذائی ماہر ماریا گردوں کے لیے موزوں گاجر اور سیب کیسرول کی اپنی ترکیب شیئر کر رہی ہیں، جو کم چکنائی، کم پوٹاشیم اور کولیسٹرول سے پاک ڈش ہے اور جسے ذیابیطس، ڈائیلاسز یا ڈائیلاسز کے بغیر دائمی گردوں کی بیماری (CKD) کی غذا پر عمل کرنے والے لوگ کھا سکتے ہیں۔","10","3/4 کپ",
["6 بڑی گاجریں","4 بڑے سیب","5 کھانے کے چمچ میدہ","2 کھانے کے چمچ براؤن شوگر","1/2 چائے کا چمچ پسا ہوا جائفل","3 کھانے کے چمچ مکھن","1/2 کپ سیب کا جوس"],
["اوون کو 350° F پر پہلے سے گرم کریں۔","گاجروں اور سیبوں کو چھیل کر کاٹ لیں۔ ایک درمیانے برتن میں 1 کوارٹ پانی ابال لیں۔ گاجروں کو 5 منٹ یا نرم ہونے تک ابالیں۔ پانی نکال دیں۔","گاجروں اور سیبوں کی تہیں ایک بڑی کیسرول ڈش میں لگائیں۔","ایک چھوٹے پیالے میں کانٹے سے میدہ، براؤن شوگر اور جائفل ملائیں۔ مکھن ملا کر چورا نما ٹاپنگ بنائیں۔","میدے کا مکسچر گاجروں اور سیبوں پر چھڑکیں، پھر اوپر سے جوس ڈالیں۔","50 منٹ یا جب تک سیب اور گاجریں نرم اور ٹاپنگ سنہری بھوری نہ ہو جائے بیک کریں۔"],
["چھیلنے اور کاٹنے کے بعد چھ بڑی گاجروں سے 6 کپ اور 4 بڑے سیبوں سے 4 کپ حاصل ہوتے ہیں۔","کیسرول کو پہلے سے تیار کر کے فرج میں رکھا جا سکتا ہے۔ کھانے کے لیے تیار ہونے پر گرم کر لیں۔","اگر کم کاربوہائیڈریٹ مواد چاہیے تو براؤن شوگر کی جگہ Splenda® سویٹنر استعمال کریں۔"],
["1 پھل، کم پوٹاشیم والا","1 سبزی، درمیانے پوٹاشیم والی","1/2 چکنائی"]))
